	private Map<String, Long> sourceWork(String name, String indexes, int runSize, boolean grouped) throws Exception {
		return sourceWork(name, indexes, runSize, grouped, true);
	}

	private Map<String, Long> sourceWork(String name, String indexes, int runSize, boolean grouped,
			boolean countRunRows) throws Exception {
		LmdbStoreConfig config = indexes.equals("default") || indexes.equals("estimator-disabled")
				? new LmdbStoreConfig()
				: new LmdbStoreConfig(indexes);
		if (indexes.equals("estimator-disabled")) {
			config.setPageCardinalityEstimator(false);
		}
		config.setNativeEvaluationEnabled(true).setDirectAdjacencyEnabled(false);
		LmdbStore store = new LmdbStore(directory.resolve(name).toFile(), config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			var values = repository.getValueFactory();
			var first = values.createIRI("urn:index-count:first");
			var second = values.createIRI("urn:index-count:second");
			try (var connection = repository.getConnection()) {
				connection.begin();
				for (int index = 0; index < runSize; index++) {
					connection.add(values.createIRI("urn:index-count:s:" + index), first, values.createLiteral(index));
					connection.add(values.createIRI("urn:index-count:s:" + index), second, values.createLiteral(index));
				}
				connection.commit();
			}
			try (var dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
				NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
				long firstId = source.idOf(first);
				if (!grouped) {
					LmdbPrefixRunPlan.resetMetrics();
					try (LmdbStartupReadCounter reads = adjacencyReads(store)) {
						assertThat(source.count(-1L, firstId, -1L, -1L)).isEqualTo(runSize);
						return work(indexes, name, runSize, grouped, countRunRows, reads.operations());
					}
				}
				LmdbPrefixRunPlan plan = source.prefixRunPlan(new int[] { TripleIndex.PRED_IDX }, -1L, -1L, -1L, -1L);
				assertThat(plan).as("the configured predicate-leading index can enumerate grouped prefixes")
						.isNotNull();
				LmdbPrefixRunPlan.resetMetrics();
				try (LmdbStartupReadCounter reads = adjacencyReads(store);
						LmdbPrefixRunCursor runs = source.prefixRuns(plan, -1L, -1L, -1L, -1L, countRunRows)) {
					int groups = 0;
					while (runs.next()) {
						assertThat(runs.runRowCount()).isEqualTo(countRunRows ? runSize : 1L);
						groups++;
					}
					assertThat(groups).isEqualTo(2);
					runs.close();
					return work(indexes, name, runSize, grouped, countRunRows, reads.operations());
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	private static LmdbStartupReadCounter adjacencyReads(LmdbStore store) throws IOException {
		return store.getBackingStore()
				.getTripleStore()
				.getTxnManager()
				.doWith((stack, txn) -> new LmdbStartupReadCounter(LMDB.mdb_txn_env(txn),
						LmdbPersistentAdjacency.openExisting(txn).metadataDbi()));
	}

	private static Map<String, Long> work(String indexes, String name, int runSize, boolean grouped,
			boolean countRunRows, Map<String, Long> reads) {
		Map<String, Long> work = new HashMap<>(reads);
		work.put("adjacency_count_get", reads.getOrDefault("adjacency_count_get", 0L));
		System.out.printf("PERSISTENT_AGGREGATE_WORK indexes=%s fixture=%s runSize=%d grouped=%s counting=%s work=%s%n",
				indexes, name, runSize, grouped, countRunRows, work);
		return work;
	}
